A measurable partition $B_1,\ldots,B_k$ of $\mathbb R^d$ is \emph{weakly proper} if, for every $i$ and $R>0$,
\begin{equation}\label{eq:weak}
 \int_{B(0,R)}\int_{S^{d-1}}
 \mathbf 1_{B_i}(x)\mathbf 1_{B_i}(x+u)\,d\sigma_d(u)\,dx=0.
\end{equation}

\label{thm:rigidity}
Every rotation-invariant Borel probability measure $\nu$ on $D$
satisfying $\nu(C)=0$ equals $m_D$.
